import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Navigate } from 'react-router-dom';
import AddProductModal from '../components/AddProductModal';
import ProductCard from '../components/ProductCard';
import { PlusIcon, PencilIcon, TrashIcon } from '@heroicons/react/24/outline';
import axios from 'axios';

const FarmerDashboard = () => {
  const { user, token } = useAuth();
  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);
  const [loading, setLoading] = useState(true);

  // Fixed prices for vegetables (per kg)
  const fixedPrices = {
    tomato: 40,
    onion: 30,
    potato: 25,
    carrot: 35,
    cabbage: 20,
    cauliflower: 45,
    spinach: 50,
    broccoli: 60,
    cucumber: 30,
    capsicum: 55,
    eggplant: 35,
    okra: 40
  };

  useEffect(() => {
    if (user) {
      loadFarmerProducts();
      loadFarmerOrders();
    }
  }, [user]);

  const loadFarmerProducts = async () => {
    if (!user || !token) return;

    try {
      const response = await axios.get(`http://localhost:3000/api/products/farmer/${user.id}`, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      setProducts(response.data);
    } catch (error) {
      console.error('Error loading farmer products:', error);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  const loadFarmerOrders = () => {
    const allOrders = JSON.parse(localStorage.getItem('farm2home_orders') || '[]');
    const farmerOrders = allOrders.filter(order =>
      order.items.some(item =>
        item.farmer.name === user.name || item.farmerId === user.id
      )
    );
    setOrders(farmerOrders);
  };

  const handleAddProduct = async (productData) => {
    const newProduct = {
      ...productData,
      price: fixedPrices[productData.category]
    };

    try {
      await axios.post('http://localhost:3000/api/products', newProduct, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      await loadFarmerProducts();
      setShowAddModal(false);
    } catch (error) {
      console.error('Error adding product:', error);
      alert('Could not add product. Please try again.');
    }
  };

  const handleEditProduct = (product) => {
    setEditingProduct(product);
    setShowAddModal(true);
  };

  const handleUpdateProduct = async (productData) => {
    if (!editingProduct) return;

    const updatedProduct = {
      ...editingProduct,
      ...productData,
      price: fixedPrices[productData.category]
    };

    try {
      await axios.put(`http://localhost:3000/api/products/${editingProduct._id || editingProduct.id}`, updatedProduct, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      await loadFarmerProducts();
      setShowAddModal(false);
      setEditingProduct(null);
    } catch (error) {
      console.error('Error updating product:', error);
      alert('Could not update product. Please try again.');
    }
  };

  const handleDeleteProduct = async (productId) => {
    if (!window.confirm('Are you sure you want to delete this product?')) return;

    try {
      await axios.delete(`http://localhost:3000/api/products/${productId}`, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      await loadFarmerProducts();
    } catch (error) {
      console.error('Error deleting product:', error);
      alert('Could not delete product. Please try again.');
    }
  };

  if (!user || user.userType !== 'farmer') {
    return <Navigate to="/login" />;
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            Welcome back, {user.name}! 🚜
          </h1>
          <p className="text-gray-600">
            Manage your vegetables and track your orders
          </p>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white p-6 rounded-lg shadow-sm">
            <div className="flex items-center">
              <div className="p-2 bg-green-100 rounded-lg">
                <span className="text-2xl">🥬</span>
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-600">Total Products</p>
                <p className="text-2xl font-bold text-gray-900">{products.length}</p>
              </div>
            </div>
          </div>

          <div className="bg-white p-6 rounded-lg shadow-sm">
            <div className="flex items-center">
              <div className="p-2 bg-blue-100 rounded-lg">
                <span className="text-2xl">📦</span>
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-600">Total Orders</p>
                <p className="text-2xl font-bold text-gray-900">{orders.length}</p>
              </div>
            </div>
          </div>

          <div className="bg-white p-6 rounded-lg shadow-sm">
            <div className="flex items-center">
              <div className="p-2 bg-yellow-100 rounded-lg">
                <span className="text-2xl">💰</span>
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-600">Revenue</p>
                <p className="text-2xl font-bold text-gray-900">
                  ₹{orders.reduce((total, order) => total + order.total, 0)}
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* My Products Section */}
        <div className="mb-8">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-bold text-gray-900">My Products</h2>
            <button
              onClick={() => setShowAddModal(true)}
              className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-md flex items-center space-x-2 transition-colors duration-200"
            >
              <PlusIcon className="w-5 h-5" />
              <span>Add Product</span>
            </button>
          </div>

          {products.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-lg">
              <div className="text-6xl mb-4">🥬</div>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">
                No products yet
              </h3>
              <p className="text-gray-600 mb-4">
                Start by adding your first vegetable to the marketplace
              </p>
              <button
                onClick={() => setShowAddModal(true)}
                className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-md"
              >
                Add Your First Product
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {products.map(product => (
                <div key={product._id || product.id} className="relative">
                  <ProductCard product={product} showAddToCart={false} />
                  <div className="absolute top-2 left-2 flex space-x-1">
                    <button
                      onClick={() => handleEditProduct(product)}
                      className="bg-blue-600 hover:bg-blue-700 text-white p-1 rounded-full"
                    >
                      <PencilIcon className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDeleteProduct(product._id)}
                      className="bg-red-600 hover:bg-red-700 text-white p-1 rounded-full"
                    >
                      <TrashIcon className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Recent Orders Section */}
        <div>
          <h2 className="text-2xl font-bold text-gray-900 mb-6">Recent Orders</h2>

          {orders.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-lg">
              <div className="text-6xl mb-4">📦</div>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">
                No orders yet
              </h3>
              <p className="text-gray-600">
                Orders will appear here when customers purchase your vegetables
              </p>
            </div>
          ) : (
            <div className="bg-white rounded-lg shadow-sm overflow-hidden">
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Order ID
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Customer
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Items
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Total
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Status
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Date
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {orders.map(order => (
                      <tr key={order.id}>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                          #{order.id.toString().slice(-6)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          {order.customerName}
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-900">
                          {order.items
                            .filter(item => item.farmer.name === user.name)
                            .map(item => `${item.name} (${item.quantity}kg)`)
                            .join(', ')}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          ₹{order.items
                            .filter(item => item.farmer.name === user.name)
                            .reduce((total, item) => total + (item.price * item.quantity), 0)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">
                            {order.status}
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {new Date(order.createdAt).toLocaleDateString()}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {/* Fixed Prices Info */}
        <div className="mt-8 bg-green-50 p-6 rounded-lg">
          <h3 className="text-lg font-semibold text-green-800 mb-4">
            Fixed Price System 💰
          </h3>
          <p className="text-green-700 mb-4">
            All vegetables are sold at system-defined fixed prices to ensure fairness.
          </p>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            {Object.entries(fixedPrices).map(([vegetable, price]) => (
              <div key={vegetable} className="flex justify-between">
                <span className="capitalize">{vegetable}:</span>
                <span className="font-semibold">₹{price}/kg</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Add/Edit Product Modal */}
      {showAddModal && (
        <AddProductModal
          isOpen={showAddModal}
          onClose={() => {
            setShowAddModal(false);
            setEditingProduct(null);
          }}
          onSubmit={editingProduct ? handleUpdateProduct : handleAddProduct}
          product={editingProduct}
          fixedPrices={fixedPrices}
        />
      )}
    </div>
  );
};

export default FarmerDashboard;
